import test from 'node:test';
import assert from 'node:assert/strict';
import { recordPayment, balanceDue } from '../src/payments.js';
import { createInvoice, issueInvoice, invoiceTotals } from '../src/invoices.js';

test('recordPayment rejects draft invoices', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const result = recordPayment(invoiceResult.value, { amount: 1000, date: '2025-10-08' });
  assert.deepEqual(result, { ok: false, error: 'NOT_ISSUED' });
});

test('recordPayment rejects negative amounts', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const invoice = issuedResult.value;

  const result = recordPayment(invoice, { amount: -1000, date: '2025-10-08' });
  assert.deepEqual(result, { ok: false, error: 'AMOUNT_INVALID' });
});

test('recordPayment rejects zero amounts', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const invoice = issuedResult.value;

  const result = recordPayment(invoice, { amount: 0, date: '2025-10-08' });
  assert.deepEqual(result, { ok: false, error: 'AMOUNT_INVALID' });
});

test('recordPayment rejects non-integer amounts', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const invoice = issuedResult.value;

  const result = recordPayment(invoice, { amount: 1000.50, date: '2025-10-08' });
  assert.deepEqual(result, { ok: false, error: 'AMOUNT_INVALID' });
});

test('recordPayment rejects overpayment', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const invoice = issuedResult.value;

  const totals = invoiceTotals(invoice);

  const result = recordPayment(invoice, { amount: totals.total + 1, date: '2025-10-08' });
  assert.deepEqual(result, { ok: false, error: 'OVERPAYMENT' });
});

test('recordPayment accepts payment on issued invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const invoice = issuedResult.value;

  const result = recordPayment(invoice, { amount: 30000, date: '2025-10-08' });
  assert.equal(result.ok, true);
  assert.equal(result.value.status, 'partially_paid');
  assert.equal(result.value.payments.length, 1);
  assert.deepEqual(result.value.payments[0], { amount: 30000, date: '2025-10-08' });
});

test('recordPayment sets status to paid when fully paid', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const invoice = issuedResult.value;

  const totals = invoiceTotals(invoice);

  const result = recordPayment(invoice, { amount: totals.total, date: '2025-10-08' });
  assert.equal(result.ok, true);
  assert.equal(result.value.status, 'paid');
});

test('recordPayment accumulates multiple payments', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const invoice = issuedResult.value;

  const totals = invoiceTotals(invoice);

  const payment1 = recordPayment(invoice, { amount: 20000, date: '2025-10-08' });
  assert.equal(payment1.ok, true);
  assert.equal(payment1.value.status, 'partially_paid');
  assert.equal(payment1.value.payments.length, 1);

  const payment2 = recordPayment(payment1.value, { amount: 20000, date: '2025-10-09' });
  assert.equal(payment2.ok, true);
  assert.equal(payment2.value.status, 'partially_paid');
  assert.equal(payment2.value.payments.length, 2);

  const payment3 = recordPayment(payment2.value, { amount: totals.total - 40000, date: '2025-10-10' });
  assert.equal(payment3.ok, true);
  assert.equal(payment3.value.status, 'paid');
  assert.equal(payment3.value.payments.length, 3);
  assert.deepEqual(payment3.value.payments, [
    { amount: 20000, date: '2025-10-08' },
    { amount: 20000, date: '2025-10-09' },
    { amount: totals.total - 40000, date: '2025-10-10' },
  ]);
});

test('recordPayment accepts payments on partially_paid invoices', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const invoice = issuedResult.value;

  const payment1 = recordPayment(invoice, { amount: 10000, date: '2025-10-08' });
  assert.equal(payment1.ok, true);
  assert.equal(payment1.value.status, 'partially_paid');

  const payment2 = recordPayment(payment1.value, { amount: 10000, date: '2025-10-09' });
  assert.equal(payment2.ok, true);
  assert.equal(payment2.value.status, 'partially_paid');
});

test('balanceDue returns full amount for unpaid issued invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const invoice = issuedResult.value;

  const expected = invoiceTotals(invoice).total;
  const due = balanceDue(invoice);
  assert.equal(due, expected);
});

test('balanceDue returns remaining amount after partial payment', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const invoice = issuedResult.value;

  const totalBefore = invoiceTotals(invoice).total;
  const payment = recordPayment(invoice, { amount: 30000, date: '2025-10-08' });
  const due = balanceDue(payment.value);
  assert.equal(due, totalBefore - 30000);
});

test('balanceDue returns zero for fully paid invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const invoice = issuedResult.value;

  const totals = invoiceTotals(invoice);
  const payment = recordPayment(invoice, { amount: totals.total, date: '2025-10-08' });
  assert.equal(payment.ok, true);
  const due = balanceDue(payment.value);
  assert.equal(due, 0);
});

test('recordPayment does not mutate the original invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const invoice = issuedResult.value;

  const originalStatus = invoice.status;
  const originalPayments = invoice.payments;

  recordPayment(invoice, { amount: 10000, date: '2025-10-08' });

  assert.equal(invoice.status, originalStatus);
  assert.equal(invoice.payments, originalPayments);
});

test('balanceDue works with invoices with multiple lines and discounts', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'DES-HOUR', qty: 5 },
    ],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const invoice = issuedResult.value;

  const due = balanceDue(invoice);
  assert(due > 0);

  const payment = recordPayment(invoice, { amount: 50000, date: '2025-10-08' });
  assert.equal(payment.ok, true);

  const remainingDue = balanceDue(payment.value);
  assert.equal(remainingDue, due - 50000);
